html:
{%- set creditor = doc.client_name or doc.client or "" -%}
{%- set cur = doc.debt_currency or "BHD" -%}
{%- set amount = "{:,.3f}".format(doc.debt_balance_amount or 0) -%}
{%- set today = frappe.utils.formatdate(frappe.utils.nowdate(), "d MMMM yyyy") -%}
{%- set debtor = (doc.debtor_name or "") -%}
<style>
@page { size: A4; margin: 0; }
.print-format { margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; padding: 0; }
.pg { position: relative; width: 594.96pt; height: 835pt; margin: 0 auto; overflow: hidden; background: #fff; color: #000;
  font-family: Arial, Helvetica, "Liberation Sans", sans-serif; font-size: 9pt; line-height: 10.35pt; }
.pg .a { position: absolute; margin: 0; padding: 0; white-space: nowrap; }
.pg .en { left: 43.9pt; direction: ltr; text-align: left; }
.pg .ar { right: 50.2pt; width: 246.5pt; font-size: 9.34pt; direction: rtl; text-align: right; white-space: normal; }
.pg .ltr-r { right: 49.1pt; font-size: 9pt; direction: ltr; text-align: right; }
.pg .th { font-family: Tahoma, Verdana, Arial, sans-serif; font-weight: bold; letter-spacing: -0.033em; color: #101010; text-align: center; left: 0; width: 594.96pt; }
.pg .flow p { margin: 0 0 6.15pt 0; padding: 0; white-space: nowrap; }
.pg .enf { left: 43.9pt; width: 250pt; direction: ltr; text-align: left; white-space: normal; }
.pg .enf p.wr { white-space: normal; }
.pg .arf { right: 50.2pt; width: 246.5pt; direction: rtl; text-align: right; font-size: 9.34pt; }
.pg .arf p { white-space: normal; }
.pg b { font-weight: bold; }
.pg .u { text-decoration: underline; font-weight: bold; }
.pg .nm { text-decoration: underline; text-transform: uppercase; }
.pg img { position: absolute; }
.pg .ln { position: absolute; left: 42.75pt; width: 509.25pt; top: 678pt; height: 0.75pt; background: #dcdcdc; }
.pg .ft { position: absolute; top: 683.7pt; left: 0; width: 574.96pt; text-align: center; font-size: 7.4pt; color: #666; line-height: 9pt; }
</style>
<div class="pg">
<img src="/assets/debt_recovery/images/primegulf_logo.jpg" style="left:78pt;top:50.2pt;width:84.7pt;height:56.3pt">
<img src="/assets/debt_recovery/images/primegulf_header_text.png" style="left:226pt;top:53pt;width:298pt;height:57pt">
<div class="a" style="left:48.7pt;top:123.3pt;font-family:Tahoma,Verdana,Arial,sans-serif;font-weight:bold;letter-spacing:-0.033em;font-size:9.6pt;line-height:11.5pt;color:#101010">{{ today }}</div>
<div class="a th" style="top:152.9pt;font-size:11pt;line-height:13.2pt;letter-spacing:-0.018em;">CURRENT PENDING BALANCE NOTICE as of {{ today }} is {{ cur }} {{ amount }} due to<br>{{ creditor }}</div>
<div class="a th" style="top:206.1pt;font-size:12pt;line-height:14.4pt;letter-spacing:-0.006em;"><span class="nm">{{ debtor }}</span></div>
<div class="a flow enf" style="top:261.1pt"><p class=""><b>Dear {{ debtor }},</b></p><p class="">Greetings from <b>Prime Gulf Global Recoveries W.L.L.</b></p><p class="wr">We are writing on behalf of <b>{{ creditor }}</b> regarding the <b>current pending balance of {{ cur }} {{ amount }}</b> under your account as of today.</p><p class="">We kindly request you to settle the outstanding balance or<br>contact us immediately to discuss a settlement or payment<br>arrangement.</p><p class=""><span class="u">Prompt action is requested to avoid further payment<br>reminders, formal demand notices, and possible<br>escalation of the matter to the next stage.</span></p><p class="">If payment has already been made, please provide us with the<br>payment receipt for our records.</p><p class="">For assistance, please contact us at <b>+973 3304 6888</b>,<br>between <b>8:00 AM</b> and <b>5:00 PM</b>.</p><p class="">Yours faithfully,<br><b>Prime Gulf Global Recoveries W.L.L.</b></p></div><div class="a flow arf" style="top:261.1pt"><p style=""><b>السيد/السيدة: {{ debtor }}،</b></p><p style="">تحية طيبة من <b>شركة برايم جلف العالمية لتحصيل الديون ذ.م.م.</b></p><p style="">نتواصل معكم نيابةً عن <b>{{ creditor }}</b> بخصوص <b>الرصيد المستحق الحالي البالغ {{ amount }} دينار بحريني</b> على حسابكم.</p><div style="height:16.5pt"></div><p style="">نرجو منكم التكرم بسداد المبلغ المستحق أو التواصل معنا فوراً لمناقشة التسوية أو ترتيب خطة للسداد.</p><div style="height:16.5pt"></div><p style=""><b>يرجى المبادرة باتخاذ الإجراء اللازم لتجنب إرسال المزيد من تذكيرات الدفع أو<br>إشعارات المطالبة الرسمية، وكذلك لتجنب تصعيد الموضوع إلى المرحلة<br>التالية.</b></p><div style="height:16.5pt"></div><p style="">في حال سبق لكم سداد المبلغ، يرجى تزويدنا بإيصال الدفع لأغراض السجلات.</p><p style="">للمساعدة والاستفسارات، يرجى التواصل معنا على الرقم <b><bdi dir="ltr">+973 3304 6888</bdi></b>، من الساعة <b>8:00 صباحاً حتى 5:00 مساءً</b>.</p><p style="">وتفضلوا بقبول فائق الاحترام والتقدير،</p><p style="direction:ltr;text-align:right"><b>Prime Gulf Global Recoveries W.L.L.</b></p></div>
<img src="/assets/debt_recovery/images/primegulf_signature.png" style="left:230.2pt;top:524.3pt;width:60pt;height:45pt"><img src="/assets/debt_recovery/images/primegulf_stamp.png" style="left:293.2pt;top:524.3pt;width:86.3pt;height:84.8pt">
<div class="ln"></div><div class="ft"><span dir="ltr">+973 3304 6888 | www.primegulf.bh | info@primegulf.bh</span></div>
</div>
